#compdef foo

# zsh completion support for foo v2.6.0

autoload -U is-at-least

# shellcheck disable=SC2154
(( $+functions[__foo_complete] )) ||
function __foo_complete {
  local name="$1"; shift
  local action="$1"; shift
  integer ret=1
  local -a values
  local expl lines
  _tags "$name"
  while _tags; do
    if _requested "$name"; then
      # shellcheck disable=SC2034
      lines="$(foo completions complete "${action}" "${@}")"
      values=("${(ps:\n:)lines}")
      if (( ${#values[@]} )); then
        while _next_label "$name" expl "$action"; do
          compadd -S '' "${expl[@]}" "${values[@]}"
        done
      fi
    fi
  done
}

# shellcheck disable=SC2154
_foo() {
  local state

  function _commands() {
    local -a commands
    # shellcheck disable=SC2034
    commands=(
      'auth:Manage Linear authentication'
      'issue:Manage Linear issues'
      'team:Manage Linear teams'
      'user:Manage Linear users'
      'project:Manage Linear projects'
      'project-update:Manage project status updates'
      'cycle:Manage Linear team cycles'
      'milestone:Manage Linear project milestones'
      'initiative:Manage Linear initiatives'
      'initiative-update:Manage initiative status updates (timeline posts)'
      'label:Manage Linear issue labels'
      'template:Browse Linear issue, project, and document templates. Apply one with `issue create --template` or `project create --template`.'
      'document:Manage Linear documents'
      'completions:Generate shell completions.'
      'config:Interactively generate .linear.toml configuration'
      'schema:Print the GraphQL schema to stdout'
      'api:Make a raw GraphQL API request'
      'markdown:Linear-flavored Markdown: mentions and collapsible sections'
    )
    _describe 'command' commands
  }

  function _command_args() {
    case "${words[1]}" in
      auth) _foo_auth ;;
      issue|i) _foo_issue ;;
      team|t) _foo_team ;;
      user|u) _foo_user ;;
      project|p) _foo_project ;;
      project-update|pu) _foo_project_update ;;
      cycle|cy) _foo_cycle ;;
      milestone|m) _foo_milestone ;;
      initiative|init) _foo_initiative ;;
      initiative-update|iu) _foo_initiative_update ;;
      label|l) _foo_label ;;
      template) _foo_template ;;
      document|docs|doc) _foo_document ;;
      completions) _foo_completions ;;
      config|configure) _foo_config ;;
      schema) _foo_schema ;;
      api) _foo_api ;;
      markdown) _foo_markdown ;;
    esac
  }

  _arguments -w -s -S -C \
    '(- *)'{-h,--help}'[Show this help.]' \
    '(- *)'{-V,--version}'[Show the version number for this program.]' \
    '(-h --help -V --version --workspace)'--workspace'[Target workspace (uses credentials)]:slug:->slug-string' \
    '1:command:_commands' \
    '*::sub command:->command_args'

  case "$state" in
    command_args) _command_args ;;
    slug-string) __foo_complete slug string  ;;
  esac
}

